3	import { cache } from "react";
4	import { redirect } from "next/navigation";
5	import { createClient } from "@/lib/supabase/server";
6	import type { Capability } from "@/lib/auth/capabilities";
7	
8	export type Role = "member" | "moderator" | "admin";
9	
10	export type SessionUser = {
11	  id: string;
12	  email: string | null;
13	  role: Role;
14	  capabilities: string[];
15	  username: string | null;
16	  displayName: string | null;
17	  avatarUrl: string | null;
18	  isBanned: boolean;
19	  needsOnboarding: boolean;
20	};
21	
22	/** Does this user hold a capability? Admins (superusers) hold all of them. */
23	export function userCan(
24	  user: SessionUser | null,
25	  cap: Capability,
26	): boolean {
27	  if (!user) return false;
28	  return user.role === "admin" || user.capabilities.includes(cap);
29	}
30	
31	/**
32	 * Data Access Layer. Following the Next.js 16 auth guidance, authorization
33	 * checks live here (close to the data) rather than in a layout or proxy.
34	 * `cache` memoizes the lookup for a single render pass.
35	 */
36	export const getSessionUser = cache(async (): Promise<SessionUser | null> => {
37	  const supabase = await createClient();
38	  const {
39	    data: { user },
40	  } = await supabase.auth.getUser();
41	  if (!user) return null;
42	
43	  const { data: profile } = await supabase
44	    .from("profiles")
45	    .select(
46	      "role, capabilities, username, display_name, avatar_url, is_banned, onboarded_at",
47	    )
48	    .eq("id", user.id)
49	    .single();
50	
51	  return {
52	    id: user.id,
53	    email: user.email ?? null,
54	    role: (profile?.role as Role) ?? "member",
55	    capabilities: (profile?.capabilities as string[]) ?? [],
56	    username: profile?.username ?? null,
57	    displayName: profile?.display_name ?? null,
58	    avatarUrl: profile?.avatar_url ?? null,
59	    isBanned: profile?.is_banned ?? false,
60	    needsOnboarding: profile ? !profile.onboarded_at : false,
61	  };
62	});
63	
64	/**
65	 * Require an authenticated, non-banned, onboarded user. Un-onboarded users are
66	 * sent to the required registration survey — this is the gate that makes the
67	 * survey unskippable: every authed page and every server action flows through
68	 * here. (The onboarding page + submit action use getSessionUser to avoid it.)
69	 */
70	export async function requireUser(): Promise<SessionUser> {
71	  const user = await getSessionUser();
72	  if (!user) redirect("/login");
73	  if (user.isBanned) redirect("/banned");
74	  if (user.needsOnboarding) redirect("/onboarding");
75	  return user;
76	}
77	
78	/** Require any staff member (admin or anyone with ≥1 capability). */
79	export async function requireAdmin(): Promise<SessionUser> {
80	  const user = await requireUser();
81	  if (user.role !== "admin" && user.capabilities.length === 0) redirect("/");
82	  return user;
83	}
84	
85	/** Require a specific capability (admins always pass). */
86	export async function requireCapability(cap: Capability): Promise<SessionUser> {
87	  const user = await requireUser();
88	  if (!userCan(user, cap)) redirect("/");
89	  return user;
90	}
