69	/**
70	 * Render preview cards for the bare URLs in `body` that have a resolved entry in
71	 * `previews`. URLs still pending/errored just stay as the plain markdown link
72	 * rendered elsewhere, so nothing shows here for them.
73	 */
74	export function LinkPreviews({
75	  body,
76	  previews,
77	  limit,
78	}: {
79	  body: string;
80	  previews: Map<string, LinkPreview>;
81	  /** Cap how many cards render (e.g. 1 in a timeline list). */
82	  limit?: number;
83	}) {
84	  let cards = extractBareUrls(body)
85	    .map((url) => previews.get(url))
86	    .filter((p): p is LinkPreview => Boolean(p));
87	  if (limit !== undefined) cards = cards.slice(0, limit);
88	  if (cards.length === 0) return null;
89	  return (
90	    <div className="mt-4 flex flex-col gap-3">
91	      {cards.map((preview) => (
92	        <LinkPreviewCard key={preview.url} preview={preview} />
93	      ))}
94	    </div>
95	  );
96	}
