4	/**
5	 * Live slug availability check for the event form. Admin-only (so the query,
6	 * under RLS, can see draft events too). Returns { available: boolean | null }.
7	 */
8	export async function GET(request: Request) {
9	  const user = await getSessionUser();
10	  if (!user || (user.role !== "admin" && user.role !== "moderator")) {
11	    return Response.json({ available: null, error: "forbidden" }, { status: 403 });
12	  }
13	
14	  const { searchParams } = new URL(request.url);
15	  const slug = (searchParams.get("slug") ?? "").trim().toLowerCase();
16	  const exclude = searchParams.get("exclude");
17	  if (!slug) return Response.json({ available: null });
18	
19	  const supabase = await createClient();
20	  const { data, error } = await supabase
21	    .from("events")
22	    .select("id")
23	    .eq("slug", slug)
24	    .maybeSingle();
25	  if (error) {
26	    return Response.json({ available: null, error: error.message }, { status: 500 });
27	  }
28	
29	  // Available if nothing matches, or the only match is the event being edited.
30	  const available = !data || (exclude != null && data.id === exclude);
31	  return Response.json({ available, slug });
32	}
