1	import { createAdminClient } from "@/lib/supabase/admin";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { LINK_PREVIEW_BUCKET } from "@/lib/links/constants";
4	import { resolveAndStore } from "@/lib/links/unfurl";
5	
6	/**
7	 * Maintenance for link previews. Two jobs:
8	 *
9	 *  1. Refresh — re-resolve the oldest successfully-cached previews so titles,
10	 *     images, and (importantly) dead links don't rot, and retry failed ones in
11	 *     case the source was briefly down. Bounded per run to stay well under the
12	 *     function timeout; the backlog drains over successive runs.
13	 *  2. Reclaim — delete re-hosted images no live preview row references. These
14	 *     arise when a refresh resolves a URL that no longer has an image (the
15	 *     object path is deterministic per URL, so a refresh that still has an
16	 *     image overwrites in place and never orphans).
17	 *
18	 * Invoked by Vercel Cron (see vercel.json). Auth mirrors the forum image sweep:
19	 * Vercel sends CRON_SECRET as a bearer token; anything else is rejected.
20	 */
21	const REFRESH_OK_AFTER_DAYS = 30;
22	const REFRESH_ERROR_AFTER_DAYS = 7;
23	const REFRESH_BATCH = 25;
24	const RECLAIM_GRACE_MS = 60 * 60 * 1000; // 1h — don't race a fresh upload.
25	const PAGE = 100;
26	
27	/** Every image_path still referenced by a live preview row. */
28	async function referencedPaths(supabase: SupabaseClient): Promise<Set<string>> {
29	  const refs = new Set<string>();
30	  for (let from = 0; ; from += PAGE) {
31	    const { data, error } = await supabase
32	      .from("link_previews")
33	      .select("image_path")
34	      .not("image_path", "is", null)
35	      .range(from, from + PAGE - 1);
36	    if (error) throw new Error(error.message);
37	    const rows = (data ?? []) as { image_path: string }[];
38	    for (const row of rows) refs.add(row.image_path);
39	    if (rows.length < PAGE) break;
40	  }
41	  return refs;
42	}
43	
44	export async function GET(request: Request) {
45	  const secret = process.env.CRON_SECRET;
46	  if (secret) {
47	    const auth = request.headers.get("authorization");
48	    if (auth !== `Bearer ${secret}`) {
49	      return Response.json({ error: "unauthorized" }, { status: 401 });
50	    }
51	  }
52	
53	  const supabase = createAdminClient();
54	  const now = Date.now();
55	  const okCutoff = new Date(now - REFRESH_OK_AFTER_DAYS * 86400_000).toISOString();
56	  const errCutoff = new Date(now - REFRESH_ERROR_AFTER_DAYS * 86400_000).toISOString();
57	
58	  // Phase 1 — refresh the stalest previews. Errored rows get retried sooner
59	  // (7d) than successful ones are re-checked (30d). Two simple queries rather
60	  // than a nested PostgREST or()/and() filter, which is brittle with ISO
61	  // timestamps (the '.' in millis collides with the operator separator).
62	  const stale = new Map<string, true>();
63	
64	  const { data: errRows, error: errError } = await supabase
65	    .from("link_previews")
66	    .select("url")
67	    .eq("status", "error")
68	    .lt("fetched_at", errCutoff)
69	    .order("fetched_at", { ascending: true, nullsFirst: true })
70	    .limit(REFRESH_BATCH);
71	  if (errError) {
72	    return Response.json({ error: errError.message }, { status: 500 });
73	  }
74	  for (const row of (errRows ?? []) as { url: string }[]) stale.set(row.url, true);
75	
76	  if (stale.size < REFRESH_BATCH) {
77	    const { data: okRows, error: okError } = await supabase
78	      .from("link_previews")
79	      .select("url")
80	      .eq("status", "ok")
81	      .lt("fetched_at", okCutoff)
82	      .order("fetched_at", { ascending: true, nullsFirst: true })
83	      .limit(REFRESH_BATCH - stale.size);
84	    if (okError) {
85	      return Response.json({ error: okError.message }, { status: 500 });
86	    }
87	    for (const row of (okRows ?? []) as { url: string }[]) stale.set(row.url, true);
88	  }
89	
90	  for (const url of stale.keys()) {
91	    await resolveAndStore(supabase, url);
92	  }
93	  const refreshed = stale.size;
94	
95	  // Phase 2 — reclaim orphaned re-hosted images.
96	  const referenced = await referencedPaths(supabase);
97	  const orphans: string[] = [];
98	  for (let offset = 0; ; offset += PAGE) {
99	    const { data, error } = await supabase.storage
100	      .from(LINK_PREVIEW_BUCKET)
101	      .list("", { limit: PAGE, offset });
102	    if (error) {
103	      return Response.json({ error: error.message }, { status: 500 });
104	    }
105	    const objects = data ?? [];
106	    for (const obj of objects) {
107	      if (referenced.has(obj.name)) continue;
108	      // Grace window: skip objects uploaded very recently (race with an
109	      // in-flight resolve that hasn't written its image_path yet).
110	      const stamp = obj.updated_at ?? obj.created_at;
111	      if (stamp && now - new Date(stamp).getTime() < RECLAIM_GRACE_MS) continue;
112	      orphans.push(obj.name);
113	    }
114	    if (objects.length < PAGE) break;
115	  }
116	  if (orphans.length > 0) {
117	    await supabase.storage.from(LINK_PREVIEW_BUCKET).remove(orphans);
118	  }
119	
120	  return Response.json({
121	    refreshed,
122	    reclaimed: orphans.length,
123	  });
124	}
