3	/**
4	 * Ingest endpoint for IFTTT (or any webhook) to push news items the tweet
5	 * drafter will consider. Guarded by a token in the query string
6	 * (?token=<NEWS_INGEST_SECRET>) since IFTTT's free tier can't set headers.
7	 *
8	 * Body (JSON): { source?, title, url }. Dedups on url; prunes items > 14 days.
9	 */
10	export async function POST(request: Request) {
11	  const secret = process.env.NEWS_INGEST_SECRET;
12	  const { searchParams } = new URL(request.url);
13	  if (!secret || searchParams.get("token") !== secret) {
14	    return Response.json({ error: "unauthorized" }, { status: 401 });
15	  }
16	
17	  let body: { source?: unknown; title?: unknown; url?: unknown };
18	  try {
19	    body = await request.json();
20	  } catch {
21	    return Response.json({ error: "invalid json body" }, { status: 400 });
22	  }
23	
24	  const title = String(body.title ?? "").trim().slice(0, 300);
25	  const url = String(body.url ?? "").trim();
26	  if (!title || !/^https?:\/\//i.test(url)) {
27	    return Response.json(
28	      { error: "title and an http(s) url are required" },
29	      { status: 400 },
30	    );
31	  }
32	
33	  // The IFTTT applets hardcode an unreliable `source` (one still says
34	  // "r/MachineLearning" for every subreddit). For Reddit links, trust the URL:
